// Localized blog cards for the journal index and the home journal row.
//
// The card data files are generated by tools/i18n/gen_blog_cards.py from
// the localized post JSONs, mirroring how lib/blog.ts derives the
// English cards. English keeps using lib/blog.ts directly.

import type { BlogCard } from "./blog";
import { getBlogCards } from "./blog";
import type { Locale } from "./i18n/config";
import fr from "./pages-i18n/blog-cards.fr.json";
import de from "./pages-i18n/blog-cards.de.json";
import nl from "./pages-i18n/blog-cards.nl.json";
import it from "./pages-i18n/blog-cards.it.json";
import pt from "./pages-i18n/blog-cards.pt.json";
import sv from "./pages-i18n/blog-cards.sv.json";
import da from "./pages-i18n/blog-cards.da.json";
import fi from "./pages-i18n/blog-cards.fi.json";
import pl from "./pages-i18n/blog-cards.pl.json";
import cs from "./pages-i18n/blog-cards.cs.json";
import sk from "./pages-i18n/blog-cards.sk.json";
import sl from "./pages-i18n/blog-cards.sl.json";
import hr from "./pages-i18n/blog-cards.hr.json";
import hu from "./pages-i18n/blog-cards.hu.json";
import ro from "./pages-i18n/blog-cards.ro.json";
import bg from "./pages-i18n/blog-cards.bg.json";
import el from "./pages-i18n/blog-cards.el.json";
import et from "./pages-i18n/blog-cards.et.json";
import lv from "./pages-i18n/blog-cards.lv.json";
import lt from "./pages-i18n/blog-cards.lt.json";
import mt from "./pages-i18n/blog-cards.mt.json";

const CARDS: Partial<Record<Locale, BlogCard[]>> = {
  fr: fr as BlogCard[],
  de: de as BlogCard[],
  nl: nl as BlogCard[],
  it: it as BlogCard[],
  pt: pt as BlogCard[],
  sv: sv as BlogCard[],
  da: da as BlogCard[],
  fi: fi as BlogCard[],
  pl: pl as BlogCard[],
  cs: cs as BlogCard[],
  sk: sk as BlogCard[],
  sl: sl as BlogCard[],
  hr: hr as BlogCard[],
  hu: hu as BlogCard[],
  ro: ro as BlogCard[],
  bg: bg as BlogCard[],
  el: el as BlogCard[],
  et: et as BlogCard[],
  lv: lv as BlogCard[],
  lt: lt as BlogCard[],
  mt: mt as BlogCard[],
};

export function getBlogCardsLocalized(locale: Locale): BlogCard[] {
  if (locale === "en") return getBlogCards();
  return CARDS[locale] ?? getBlogCards();
}
